pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 pad) internal {
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == 0);
    }

    function testFuzz_run(uint256 pad) public {
        _run(pad);
    }

    receive() external payable {}
}
